import java.nio.file.*;import java.util.*;import javax.tools.*;
class CompileAll {static String classpath(String[] a)throws Exception{var paths=new ArrayList<String>();for(int i=2;i<a.length;i++){paths.add(a[i]);if(Files.isDirectory(Path.of(a[i])))try(var files=Files.list(Path.of(a[i]))){paths.addAll(files.filter(p->p.toString().endsWith(".jar")).map(Path::toString).toList());}}return String.join(java.io.File.pathSeparator,paths);}public static void main(String[] a)throws Exception{Files.createDirectories(Path.of(a[1]));var sources=Files.walk(Path.of(a[0])).filter(p->p.toString().endsWith(".java")).map(Path::toString).toList();var args=new ArrayList<String>(List.of("-parameters","--release","17","-cp",classpath(a),"-d",a[1]));args.addAll(sources);int result=ToolProvider.getSystemJavaCompiler().run(null,null,null,args.toArray(String[]::new));if(result!=0)System.exit(result);System.out.println("Compiled "+sources.size()+" sources");}}
